)

// A failed query against ai_admin's own tables is a backend fault, not a
// business rule conflict. Reporting it as one tells the operator the key is
// already inactive, the approval already decided or the user already gone,
// which sends them looking for a state change that never happened.
func TestDatabaseFailuresAreNotReportedAsBusinessRuleConflicts(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	if _, err := db.Pool.Exec(ctx, syntheticLegacySchema); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{7}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	session := signIn(t, handler)

	// The API key row cannot be read at all, so the key state is unknown rather
	// than known to be inactive.
	withRenamedTable(t, db, "api_key", func() {
		response := session.do(t, handler, http.MethodPost, "/api/v1/keys/"+uuid.NewString()+"/rotate", nil)
		assertFailure(t, response, http.StatusInternalServerError, "key_rotate_failed")
	})

	// The approval request joins the workflow policy, so a broken policy table
	// hides the request status instead of proving it is no longer pending.
	withRenamedTable(t, db, "workflow_policy", func() {
		response := session.do(t, handler, http.MethodPost, "/api/v1/approvals/"+uuid.NewString()+"/approve", map[string]any{"comment": "확인했습니다."})
		assertFailure(t, response, http.StatusInternalServerError, "approval_failed")
	})

	// A legacy link already held by another account fails the update with a
	// unique violation; the target user exists and must not be reported missing.
	legacyUserID := uuid.New()
	if _, err := db.Pool.Exec(ctx, `INSERT INTO aiportal.user_info(user_id,user_nm,email) VALUES($1,'레거시 사용자','legacy@example.com')`, legacyUserID); err != nil {
		t.Fatal(err)
	}
	if _, err := db.Pool.Exec(ctx, `INSERT INTO ai_admin.app_user(id,username,display_name,auth_source,status,legacy_user_id)
VALUES($1,'linked@example.com','연결된 사용자','local','active',$2)`, uuid.New(), legacyUserID); err != nil {
		t.Fatal(err)
	}
	var adminID uuid.UUID
	if err := db.Pool.QueryRow(ctx, `SELECT id FROM ai_admin.app_user WHERE username='admin@example.com'`).Scan(&adminID); err != nil {
		t.Fatal(err)
	}
	response := session.do(t, handler, http.MethodPatch, "/api/v1/users/"+adminID.String(),
		map[string]any{"legacyUserId": legacyUserID.String()})
	assertFailure(t, response, http.StatusConflict, "legacy_user_conflict")
	var stillLinked uuid.UUID
	if err := db.Pool.QueryRow(ctx, `SELECT coalesce(legacy_user_id,'00000000-0000-0000-0000-000000000000')
FROM ai_admin.app_user WHERE id=$1`, adminID).Scan(&stillLinked); err != nil {
		t.Fatal(err)
	}
	if stillLinked != uuid.Nil {
		t.Fatalf("the rejected update linked the administrator anyway: %s", stillLinked)
	}
}

type sessionCredentials struct {
	cookies []*http.Cookie
	csrf    string
}

func signIn(t *testing.T, handler http.Handler) sessionCredentials {
.PHONY: all lint test build web-build docker package-offline verify-offline

VERSION := $(shell tr -d '[:space:]' < VERSION)
COMMIT := $(shell git rev-parse --short=12 HEAD 2>/dev/null || echo unknown)
BUILD_TIME := $(shell date -u +%Y-%m-%dT%H:%M:%SZ)
LDFLAGS := -X github.com/hkjang/ai-admin/internal/buildinfo.Version=v$(VERSION) -X github.com/hkjang/ai-admin/internal/buildinfo.Commit=$(COMMIT) -X github.com/hkjang/ai-admin/internal/buildinfo.BuildTime=$(BUILD_TIME)

all: lint test build

# 테스트가 잡지 못하는 회귀(서식, go vet 진단, 릴리즈 메타데이터 불일치)를 검사한다.
# CI의 lint job과 같은 명령이므로 로컬에서 먼저 확인할 수 있다.
lint:
	@unformatted=$$(gofmt -l .); \
	if [ -n "$$unformatted" ]; then \
		printf 'gofmt로 정리되지 않은 파일이 있습니다:\n%s\n' "$$unformatted" >&2; \
		exit 1; \
	fi
	go vet ./...
	./scripts/verify-version.sh

test:
	go test ./...
	cd web && npm test

web-build:
	cd web && npm ci && npm run build
	rm -rf internal/ui/dist
	cp -R web/dist internal/ui/dist

build: web-build
	mkdir -p bin
	CGO_ENABLED=0 go build -trimpath -ldflags "$(LDFLAGS)" -o bin/ai-admin ./cmd/ai-admin

docker:
	docker build --pull --build-arg VERSION=v$(VERSION) --build-arg COMMIT=$(COMMIT) --build-arg BUILD_TIME=$(BUILD_TIME) -t ai-admin:v$(VERSION) .

package-offline:
	./scripts/package-offline.sh

verify-offline:
	./scripts/verify-offline.sh

